import numpy as np
A=np.load('source_pixels.npz')['rgb'].astype(int)
for b in [10,20,50,95]:
 D=np.abs(A[b]-A[0]);
 for name,sl in [('bg',(slice(0,55),slice(None))),('table',(slice(55,90),slice(None))),('all',(slice(None),slice(None)))]:
  d=D[sl]
  print(b,name,'mean',d.mean(),'p95',np.percentile(d,95),'eq',np.mean(d==0))
PY"
